def _annealing_progress(self, start_ms, reserve):
    usable_budget_ms = max(1.0, (self.time_limit - reserve) * 1000.0)
    elapsed_ms = max(0.0, self.context.elapsed_ms() - start_ms)
    return min(1.0, elapsed_ms / usable_budget_ms)

def _within_budget(self, start_ms, reserve):
    elapsed_s = max(0.0, (self.context.elapsed_ms() - start_ms) / 1000.0)
    return elapsed_s < self.time_limit and self.context.remaining_time() > reserve

